/**
 * Handler Context Builder Module
 *
 * Builds the HandlerContext object that is passed to all route handlers.
 * Combines information from various sources into a unified context.
 *
 * @module server/runtime-handler/handler-context-builder
 */
import { buildEnrichedContext } from "../context/enriched-context.js";
import { computeContentSourceId } from "../../cache/keys.js";
import { getTrustedProxyApplicationIdentityHeaderNames } from "../../security/application-auth/trusted-proxy.js";
function configuredApplicationIdentityHeaderNames(securityConfig) {
    const trustedProxy = securityConfig?.auth?.trustedProxy;
    return trustedProxy === undefined
        ? []
        : getTrustedProxyApplicationIdentityHeaderNames(trustedProxy);
}
/**
 * Build the HandlerContext for route handlers.
 */
export function buildHandlerContext(opts) {
    const contentSourceId = opts.skipEnrichedContext ? undefined : computeContentSourceId(opts.isLocalProject, opts.resolvedEnvironment, opts.requestContext.branch, opts.releaseId);
    // Build enriched context if we have config and project slug
    const enrichedContext = !opts.skipEnrichedContext && opts.config && opts.projectSlug &&
        contentSourceId
        ? buildEnrichedContext({
            projectId: opts.projectId ?? opts.projectSlug,
            projectSlug: opts.projectSlug,
            projectDir: opts.projectDir,
            token: opts.isLocalProject ? "" : (opts.proxyToken ?? ""),
            environment: opts.resolvedEnvironment,
            branch: opts.requestContext.branch,
            isLocalProject: opts.isLocalProject,
            allowHostProjectCodeExecution: opts.allowHostProjectCodeExecution,
            contentSourceId,
            parsedDomain: opts.parsedDomain,
            adapter: opts.adapter,
            config: opts.config,
            releaseId: opts.releaseId,
            environmentName: opts.environmentName,
            moduleServerUrl: opts.moduleServerUrl,
            debug: opts.debug,
        })
        : undefined;
    return {
        projectDir: opts.projectDir,
        adapter: opts.adapter,
        moduleServerUrl: opts.moduleServerUrl,
        securityConfig: opts.securityConfig,
        requestOrigin: opts.requestOrigin,
        debug: opts.debug,
        config: opts.config,
        parsedDomain: opts.parsedDomain,
        projectSlug: opts.projectSlug,
        projectId: opts.projectId,
        releaseId: opts.releaseId,
        branchId: opts.branchId,
        branchName: opts.branchName,
        defaultBranchName: opts.defaultBranchName,
        proxyToken: opts.isLocalProject ? undefined : opts.proxyToken,
        environmentName: opts.environmentName,
        resolvedEnvironment: opts.resolvedEnvironment,
        requestContext: { ...opts.requestContext, mode: opts.resolvedEnvironment },
        routeRegistry: opts.routeRegistry,
        isLocalProject: opts.isLocalProject,
        allowHostProjectCodeExecution: opts.allowHostProjectCodeExecution,
        isProxyMode: opts.isProxyMode,
        environmentId: opts.environmentId,
        applicationIdentity: opts.applicationIdentity ?? null,
        applicationIdentityHeaderNames: opts.applicationIdentityHeaderNames ??
            configuredApplicationIdentityHeaderNames(opts.securityConfig),
        prepareHostedConfigContext: opts.prepareHostedConfigContext,
        enriched: enrichedContext,
    };
}
/**
 * Build a minimal context for monitoring endpoints.
 */
export function buildMinimalContext(projectDir, adapter, securityConfig, debug, config, requestOrigin) {
    return {
        projectDir,
        adapter,
        securityConfig,
        debug,
        config,
        requestOrigin,
        applicationIdentity: null,
        applicationIdentityHeaderNames: configuredApplicationIdentityHeaderNames(securityConfig),
    };
}
